from collections import deque

graph = {"A": ["B", "C"], "B": ["A", "D"],
         "C": ["A"], "D": ["B"]}
antrean = deque(["A"])
visited = {"A"}
while antrean:
    node = antrean.popleft()
    print(node)
    for tetangga in graph.get(node, []):
        if tetangga not in visited:
            visited.add(tetangga)
            antrean.append(tetangga)

def cari_biner(data, target):
    kiri = 0
    kanan = len(data) - 1
    while kiri <= kanan:
        tengah = (kiri + kanan) // 2
        if data[tengah] == target:
            return tengah
        if data[tengah] < target:
            kiri = tengah + 1
        else:
            kanan = tengah - 1
    return None

angka = [1, 3, 5, 7, 9]
print(cari_biner(angka, 9))
print(cari_biner(angka, 1))
print(cari_biner(angka, 8))
